import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def check_triple_gcd(U):
    """Checks constraint 1: gcd(a, b, c) = 1 for any distinct a, b, c in U."""
    if len(U) < 3:
        return False

    for subset in combinations(U, 3):
        g = gcd(subset[0], gcd(subset[1], subset[2]))
        if g != 1:
            return False
    return True

def check_divisor_constraint(U):
    """Checks constraint 2: For any two distinct x, y in U, exists z in U \ {x, y} such that z | xy."""

    U_list = list(U)
    n = len(U_list)

    for i in range(n):
        for j in range(i + 1, n):
            x = U_list[i]
            y = U_list[j]
            product = x * y

            # Check if any *other* element z divides xy
            found_divisor = False
            for k in range(n):
                if k != i and k != j:
                    z = U_list[k]
                    if product % z == 0:
                        found_divisor = True
                        break

            if not found_divisor:
                return False
    return True

def check_good_set(U):
    """Checks both constraints."""
    if len(U) < 3:
        return False

    # Sort U for canonical representation, though not strictly necessary for the check
    U = tuple(sorted(U)) 

    if not check_triple_gcd(U):
        return False

    if not check_divisor_constraint(U):
        return False

    return True

# Test the known good set U = {6, 10, 15}
U_test = [6, 10, 15]
is_good = check_good_set(U_test)

print(f"Testing U={U_test}: Good Set? {is_good}")

# Test a set that fails GCD: {2, 4, 6}
U_gcd_fail = [2, 4, 6]
is_good_gcd = check_good_set(U_gcd_fail)
print(f"Testing U={U_gcd_fail}: Good Set? {is_good_gcd}")

# Test a set that fails Divisor Constraint: {2, 3, 5}
U_divisor_fail = [2, 3, 5]
is_good_div = check_good_set(U_divisor_fail)
